// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring

const { fontFamily: interFamily } = loadInter();
const { fontFamily: oswaldFamily } = loadOswald();



export type ScoreboardProps = Record<string, any>;

// Internal component for an individual card
const PlayerCard: React.FC<{
  name: string;
  image: string;
  eventFrames: number[];
  s: number;
  frame: number;
  fps: number;
}> = ({ name, image, eventFrames, s, frame }) => {
  const sortedEvents = [...eventFrames].sort((a, b) => a - b);

  let currentScore = 0;
  let mostRecentEventFrame = -999;

  for (const ef of sortedEvents) {
    if (frame >= ef) {
      currentScore++;
      mostRecentEventFrame = ef;
    }
  }

  const t = frame - mostRecentEventFrame;
  const isAnimating = t >= 0 && t < 50;

  let scale = 1;
  let shadowOp = 0;
  let digitOffset = 0;
  let pulseScale = 0;
  let pulseOp = 0;
  let plusOneY = 0;
  let plusOneOp = 0;

  if (isAnimating) {
    // Step 1 & 4: Scale and Drop Shadow
    if (t <= 6) {
      scale = interpolate(t, [0, 6], [1, 1.04], { easing: Easing.out(Easing.quad) });
      shadowOp = interpolate(t, [0, 6], [0, 1], { easing: Easing.out(Easing.quad) });
    } else if (t <= 18) {
      scale = 1.04;
      shadowOp = 1;
    } else if (t <= 28) {
      scale = interpolate(t, [18, 28], [1.04, 1], { easing: Easing.out(Easing.quad) });
      shadowOp = interpolate(t, [18, 28], [1, 0], { easing: Easing.out(Easing.quad) });
    }

    // Step 2: Digit Roll
    if (t <= 18) {
      digitOffset = interpolate(t, [0, 18], [0, 1], { easing: Easing.bezier(0.6, 0, 0.2, 1) });
    } else {
      digitOffset = 1;
    }

    // Step 3: Pulse Ring
    if (t >= 18 && t <= 32) {
      const pt = t - 18;
      pulseScale = interpolate(pt, [0, 14], [0, 20 * s]);
      pulseOp = interpolate(pt, [0, 14], [1, 0], { easing: Easing.out(Easing.quad) });
    }

    // Step 3: +1 Label
    if (t >= 18 && t <= 30) {
      const pt = t - 18;
      plusOneY = interpolate(pt, [0, 12], [0, -20 * s], { easing: Easing.out(Easing.quad) });
      plusOneOp = interpolate(pt, [0, 12], [1, 0], { easing: Easing.out(Easing.quad) });
    }
  } else if (t >= 50 || t < 0) {
    digitOffset = 1; // Locked to current score when resting
  }

  const isRolling = isAnimating && t <= 18;
  const displayTopDigit = isRolling ? Math.max(0, currentScore - 1) : currentScore;
  const displayBottomDigit = currentScore;
  const actualOffset = isRolling ? digitOffset : 0;

  return (
    <div
      style={{
        width: 420 * s,
        height: 72 * s,
        backgroundColor: "#161616",
        borderRadius: 10 * s,
        display: "flex",
        flexDirection: "row",
        position: "relative",
        transform: `scale(${scale})`,
        transformOrigin: "center",
        boxShadow: `0 ${10 * s}px ${20 * s}px rgba(0,0,0,${shadowOp * 0.5})`,
        zIndex: isAnimating ? 10 : 1,
      }}
    >
      {/* Left Green Stripe */}
      <div
        style={{
          width: 8 * s,
          height: "100%",
          backgroundColor: "#4CAF50",
          borderTopLeftRadius: 10 * s,
          borderBottomLeftRadius: 10 * s,
        }}
      />

      {/* Main Content Area */}
      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          paddingLeft: 14 * s,
          paddingRight: 0,
        }}
      >
        {/* Photo Circle */}
        <div
          style={{
            width: 48 * s,
            height: 48 * s,
            borderRadius: 24 * s,
            backgroundColor: "#222222",
            border: `${2 * s}px solid #4CAF50`,
            boxShadow: `inset 0 0 ${10 * s}px rgba(0,0,0,0.6), 0 0 ${8 * s}px rgba(76, 175, 80, 0.4)`,
            overflow: "hidden",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {image ? (
            <Img
              src={image}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
          ) : null}
        </div>

        {/* Player Name */}
        <div
          style={{
            marginLeft: 14 * s,
            fontFamily: interFamily,
            fontWeight: 700,
            fontSize: 16 * s,
            color: "#FFFFFF",
            letterSpacing: 1.5 * s,
            textTransform: "uppercase",
            flex: 1,
          }}
        >
          {name}
        </div>
      </div>

      {/* Score Panel Wrapper (Right Edge) */}
      <div style={{ width: 80 * s, height: "100%", position: "relative" }}>
        
        {/* Pulse Ring (Behind Panel Body) */}
        {pulseOp > 0 && (
          <div
            style={{
              position: "absolute",
              top: -pulseScale,
              bottom: -pulseScale,
              left: -pulseScale,
              right: -pulseScale,
              border: `${2 * s}px solid #4CAF50`,
              borderTopRightRadius: 10 * s + pulseScale,
              borderBottomRightRadius: 10 * s + pulseScale,
              borderTopLeftRadius: 0,
              borderBottomLeftRadius: 0,
              opacity: pulseOp,
              pointerEvents: "none",
            }}
          />
        )}

        {/* Score Panel Body */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: "#0f0f0f",
            borderLeft: `${2 * s}px solid #4CAF50`,
            borderTopRightRadius: 10 * s,
            borderBottomRightRadius: 10 * s,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              height: "200%",
              transform: `translateY(${-actualOffset * 50}%)`,
            }}
          >
            <div
              style={{
                height: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: oswaldFamily,
                fontWeight: 700,
                fontSize: 28 * s,
                color: "#FFFFFF",
              }}
            >
              {displayTopDigit}
            </div>
            <div
              style={{
                height: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: oswaldFamily,
                fontWeight: 700,
                fontSize: 28 * s,
                color: "#FFFFFF",
              }}
            >
              {displayBottomDigit}
            </div>
          </div>
        </div>

        {/* +1 Floating Label */}
        {plusOneOp > 0 && (
          <div
            style={{
              position: "absolute",
              top: -15 * s + plusOneY,
              left: 0,
              right: 0,
              textAlign: "center",
              fontFamily: interFamily,
              fontWeight: 700,
              fontSize: 14 * s,
              color: "#4CAF50",
              opacity: plusOneOp,
              pointerEvents: "none",
            }}
          >
            +1
          </div>
        )}
      </div>
    </div>
  );
};

const ScoreboardGraphic: React.FC<ScoreboardProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = true,
  overallScale = 2.0,
  durationInSeconds = 25,
  player1Name = "LEWYS WARE",
  player1Image = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80",
  player2Name = "JOEL COLWILL",
  player2Image = "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80",
  player3Name = "CAMERA MAN WIL",
  player3Image = "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80",
  events = [
    { player: "Player 1 (Top)" },
    { player: "Player 2 (Middle)" },
    { player: "Player 3 (Bottom)" },
    { player: "Player 1 (Top)" },
    { player: "Player 2 (Middle)" },
    { player: "Player 1 (Top)" },
    { player: "Player 3 (Bottom)" },
    { player: "Player 2 (Middle)" },
    { player: "Player 1 (Top)" },
    { player: "Player 3 (Bottom)" },
    { player: "Player 1 (Top)" },
    { player: "Player 2 (Middle)" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = (Math.min(width, height) / 1080) * overallScale;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Map string enum to indices for easier filtering
  const mapEnumToIndex = (playerEnum: string) => {
    if (playerEnum === "Player 1 (Top)") return 0;
    if (playerEnum === "Player 2 (Middle)") return 1;
    if (playerEnum === "Player 3 (Bottom)") return 2;
    return 0;
  };

  // Dynamically calculate and space event frames evenly across video duration
  const getEventFramesForPlayer = (index: number) => {
    return events
      .map((e, idx) => {
        if (mapEnumToIndex(e.player) === index) {
          const totalEvents = events.length;
          const time = ((idx + 1) / (totalEvents + 1)) * durationInSeconds;
          return Math.floor(time * fps);
        }
        return null;
      })
      .filter((f): f is number => f !== null);
  };

  const p1Events = getEventFramesForPlayer(0);
  const p2Events = getEventFramesForPlayer(1);
  const p3Events = getEventFramesForPlayer(2);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "flex-end",
        alignItems: "center",
        paddingBottom: height * 0.15, // Places it nicely in the lower third
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 12 * s,
          position: "relative",
        }}
      >
        <PlayerCard
          name={player1Name}
          image={player1Image}
          eventFrames={p1Events}
          s={s}
          frame={frame}
          fps={fps}
        />
        <PlayerCard
          name={player2Name}
          image={player2Image}
          eventFrames={p2Events}
          s={s}
          frame={frame}
          fps={fps}
        />
        <PlayerCard
          name={player3Name}
          image={player3Image}
          eventFrames={p3Events}
          s={s}
          frame={frame}
          fps={fps}
        />
      </div>
    </AbsoluteFill>
  );
};

export default ScoreboardGraphic;